class LRUCache:
    """An LRU Cache implemented using a hash map and a circular array to achieve O(1) time complexity for get and put operations."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # key -> (value, index)
        self.circular_queue = [None] * capacity
        self.head = 0
        self.tail = 0
        self.size = 0

    def _update_queue(self, key: int):
        index = self.cache[key][1]
        if index != self.head:
            self.circular_queue[index] = None
            if index < self.head:
                for i in range(index, self.head):
                    if self.circular_queue[i] is None:
                        self.circular_queue[i] = key
                        self.cache[key] = (self.cache[key][0], i)
                        break
            else:
                for i in range(self.head, self.capacity):
                    if self.circular_queue[i] is None:
                        self.circular_queue[i] = key
                        self.cache[key] = (self.cache[key][0], i)
                        break

            self.head = (self.head + 1) % self.capacity

    def get(self, key: int) -> int:
        if key in self.cache:
            self._update_queue(key)
            return self.cache[key][0]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = (value, self.cache[key][1])
            self._update_queue(key)
        else:
            if self.size < self.capacity:
                self.circular_queue[self.tail] = key
                self.cache[key] = (value, self.tail)
                self.tail = (self.tail + 1) % self.capacity
                self.size += 1
            else:
                # Evict the least-recently used item
                lru_key = self.circular_queue[self.head]
                del self.cache[lru_key]
                self.circular_queue[self.head] = key
                self.cache[key] = (value, self.head)
                self.head = (self.head + 1) % self.capacity

class LRUCache:
    """A Least Recently Used (LRU) cache implemented using a hash map and a circular queue to facilitate O(1) access times for get and put operations."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # key -> (value, nodes reference)
        self.queue = []  # keys in the order of usage

    def get(self, key: int) -> int:
        if key in self.cache:
            value = self.cache[key][0]
            self.queue.remove(key)
            self.queue.append(key)
            return value
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = (value, self.cache[key][1])
            self.queue.remove(key)
        else:
            if len(self.cache) >= self.capacity:
                oldest_key = self.queue.pop(0)  # FIFO: remove the oldest element
                del self.cache[oldest_key]
            self.cache[key] = (value, None)
        self.queue.append(key)

class LRUCache:
    """A Least Recently Used (LRU) cache implemented using a fixed-size circular buffer and a hashmap for efficient access."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # key -> (value, index)
        self.values = [None] * capacity  # circular buffer to store values
        self.order = 0  # to track the order of insertion

    def _evict(self):
        """Evict the least recently used item based on the insertion order."""
        lru_index = self.order % self.capacity
        lru_key = None

        # Find the key associated with the LRU index
        for k, (v, idx) in self.cache.items():
            if idx == lru_index:
                lru_key = k
                break

        if lru_key is not None:
            del self.cache[lru_key]
            self.values[lru_index] = None  # Clear the value from the circular buffer

    def get(self, key: int) -> int:
        """Retrieve the value associated with the key if present, otherwise return -1."""
        if key in self.cache:
            value, index = self.cache[key]
            self.cache[key] = (value, self.order)  # Update index
            self.order += 1
            return value
        return -1

    def put(self, key: int, value: int) -> None:
        """Insert or update the value associated with the key."""
        if key in self.cache:
            self.cache[key] = (value, self.order)  # Update value and index
        else:
            if len(self.cache) >= self.capacity:
                self._evict()  # Evict the LRU item if at capacity
            self.cache[key] = (value, self.order)

        self.values[self.order % self.capacity] = value  # Store value in the circular buffer
        self.order += 1
